import re

def search_experiments(exps, patterns):
    results = []
    if isinstance(exps, dict):
        for exp_id, exp_data in exps.items():
            exp_id_lower = exp_id.lower()
            for p in patterns:
                if re.search(p, exp_id_lower):
                    results.append((exp_id, exp_data))
                    break
    elif isinstance(exps, list):
        for exp in exps:
            if isinstance(exp, dict):
                eid = exp.get("exp_id", exp.get("id", ""))
                eid_lower = eid.lower()
                for p in patterns:
                    if re.search(p, eid_lower):
                        results.append((eid, exp))
                        break
    return results

